const $=s=>document.querySelector(s), app=$("#app");
const toast=m=>{let t=$("#toast");t.textContent=m;t.style.cssText="position:fixed;right:25px;bottom:25px;background:#eeeaff;color:#111;padding:12px 17px;border-radius:10px;z-index:5";setTimeout(()=>t.style.display="none",1800)};
async function api(path,opt){let r=await fetch(path,opt);if(!r.ok)throw Error("Request failed");return r.json()}
function stat(x){return `<div class="stat"><span class="muted">${x[0]}</span><strong>${x[1]}</strong><span class="muted">${x[2]}</span></div>`}
async function render(view="overview"){
 document.querySelectorAll("nav a").forEach(a=>a.classList.toggle("active",a.dataset.view===view));
 if(view==="overview"){let v=await api("/api/vault");app.innerHTML=`<div class="hero"><div><span class="eyebrow">STARVAULT V2</span><h2>Reclaim your digital life.</h2><p class="muted">One encrypted layer for identity, personal data and consent. You decide who gets access, what they see, and when access ends.</p><button class="primary" onclick="render('vault')">Explore my vault →</button></div><div style="font-size:90px;color:#8f82ff;text-shadow:0 0 60px #7d6cff">✦</div></div><div class="stats">${stat(["Vault health",v.health+"%","Encrypted & synced"])}${stat(["Data assets",v.assets,"Across "+v.categories+" categories"])}${stat(["Active consents","04","2 expire soon"])}${stat(["Access events","128","All verified"])}</div>`}
 if(view==="vault"){let v=await api("/api/vault");app.innerHTML=`<div class="panel"><span class="eyebrow">MY VAULT</span><h2>Everything that belongs to you.</h2><p class="muted">Your data is organized into user-controlled assets. The product layer is ready for encrypted storage integration.</p><div class="grid">${v.categories.map(c=>`<div class="card"><h3>${c.name}</h3><b>${c.assets} assets</b><p class="muted">${c.coverage}% vault coverage</p><div class="bar"><i style="width:${c.coverage}%"></i></div></div>`).join("")}</div></div>`}
 if(view==="identity"){let x=await api("/api/identity/claims",{method:"POST",headers:{"Content-Type":"application/json"},body:"{}"});app.innerHTML=`<div class="panel"><span class="eyebrow">PORTABLE IDENTITY</span><h2>Proof without surrender.</h2><p class="muted">Share verified claims without handing over your entire profile.</p><div class="idcard"><div class="idmark">✦</div><div><b>STARVAULT ID</b><strong>${x.id}</strong><span>Verified · ${x.claims.length} claims</span></div></div></div>`}
 if(view==="consent"){let cs=await api("/api/consents");app.innerHTML=`<div class="panel"><span class="eyebrow">CONSENT CENTER</span><h2>Access is a permission.</h2>${cs.map(c=>`<div class="row"><div><b>${c.app}</b><small class="muted">${c.scope} · ${c.access}</small></div><span class="badge ${c.status==='expiring'?'warning':''}">${c.status}</span>${c.status!=='revoked'?`<button onclick="revoke('${c.id}')">Revoke</button>`:""}</div>`).join("")}</div>`}
 if(view==="audit"){let es=await api("/api/audit");app.innerHTML=`<div class="panel"><span class="eyebrow">AUDIT TRAIL</span><h2>Know what happened.</h2><div class="timeline">${es.map(e=>`<div><b>${e.actor}</b> ${e.action}<small>${e.time}</small></div>`).join("")}</div></div>`}
 if(view==="developer"){app.innerHTML=`<div class="panel"><span class="eyebrow">DEVELOPER PLATFORM</span><h2>Build on consent, not surveillance.</h2><p class="muted">StarVault exposes a permission layer so applications can request access without taking ownership of user data.</p><div class="code"><b>POST</b> /api/consents<br><b>GET</b> /api/identity/claims<br><b>POST</b> /api/consents/:id/revoke<br><b>EVENT</b> consent.revoked</div><p class="quote">“The internet connected people. <em>StarVault gives them control.</em>”</p></div>`}
}
async function revoke(id){await api("/api/consents/"+id+"/revoke",{method:"POST"});toast("Consent revoked");render("consent")}
document.querySelectorAll("nav a").forEach(a=>a.onclick=()=>render(a.dataset.view));
$("#add").onclick=()=>toast("Secure upload flow is next");
render();
